(async()=>{const E=window.__echoes;const t0=Date.now();
 while(Date.now()-t0<30000){const v=E.cmd('runState'); if(v.phase==='reward')break; if(v.phase==='combat')E.cmd('killAllEnemies'); await new Promise(r=>setTimeout(r,100));}
 return E.cmd('runState').phase;})()

(()=>{const out=[];
 for(const el of document.querySelectorAll('body *')){
   const r=el.getBoundingClientRect();
   if(r.width===0||r.height===0) continue;
   if(r.x<260&&r.y<140&&r.x+r.width>0&&r.y+r.height>0){
     const cs=getComputedStyle(el);
     if(cs.visibility==='hidden'||cs.display==='none'||Number(cs.opacity)===0) continue;
     out.push({tag:el.tagName, id:el.id, cls:el.className&&el.className.toString().slice(0,60), txt:(el.textContent||'').trim().slice(0,30), box:[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)], op:cs.opacity, fs:cs.fontSize, color:cs.color, z:cs.zIndex});
   }}
 return {n:out.length, out:out.slice(0,25), tick:window.__echoes.tick, phase:window.__echoes.cmd('runState').phase};})()

